for(int group=0;group<plans.Length;group++){var pair=plans.GetValue(group);var plan=pair.GetType().GetProperty("Value").GetValue(pair);VerifyNative(sl,plan,ix,true);var positions=(Vector3[])Get(plan,"Positions");var tex=new Dictionary<int,Vector2>();foreach(var d in (Array)Get(plan,"PreparedDomains"))foreach(System.Collections.DictionaryEntry entry in (System.Collections.IDictionary)Get(d,"Uvs"))tex[(int)entry.Key]=(Vector2)entry.Value;foreach(var f in (Array)Get(plan,"Fragments")){var ids=(int[])Get(f,"Indices");for(int at=0;at<ids.Length;at+=3)all.Add(((int)Get(f,"Triangle"),group,ids.Skip(at).Take(3).Select(i=>positions[i]).ToArray(),ids.Skip(at).Take(3).Select(i=>tex[i]).ToArray()));}}
dump.Write(all.Count);foreach(var t in all){dump.Write(t.face);dump.Write(t.material);for(int i=0;i<3;i++){dump.Write(t.positions[i].x);dump.Write(t.positions[i].y);dump.Write(t.positions[i].z);dump.Write(t.uv[i].x);dump.Write(t.uv[i].y);}}
Debug.Log("LIFT02_UNDERLAY71_PASS lod="+lod+" input="+label+" triangles="+all.Count);
}}
